def list_all(path, max_depth=2):
    results = []
    if not os.path.isdir(path):
        return results
    for root, dirs, files in os.walk(path):
        depth = root.replace(path, '').count(os.sep)
        if depth > max_depth:
            continue
        for f in files:
            results.append(os.path.join(root, f))
    return results

